--
-- Table structure for table `results`
--

CREATE TABLE `results` (
  `id` varchar(100) NOT NULL,
  `user_email` varchar(100) DEFAULT NULL,
  `examId` varchar(100) DEFAULT NULL,
  `examName` varchar(200) DEFAULT NULL,
  `answerSet` varchar(50) DEFAULT NULL,
  `studentCode` varchar(100) DEFAULT NULL,
  `studentName` varchar(200) DEFAULT NULL,
  `sheetId` varchar(100) DEFAULT NULL,
  `score` float DEFAULT NULL,
  `total` int(11) DEFAULT NULL,
  `percent` float DEFAULT NULL,
  `answers` text DEFAULT NULL,
  `flagged` tinyint(1) DEFAULT NULL,
  `wrong` text DEFAULT NULL,
  `skipped` text DEFAULT NULL,
  `summary` text DEFAULT NULL,
  `metadata_json` text DEFAULT NULL,
  `imageUrl` varchar(500) DEFAULT NULL,
  `createdAt` datetime DEFAULT NULL,
  `timestamp` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

